using System;
using System.Collections.Generic;

public class Solution {
    public IList<int> EventualSafeNodes(int[][] graph) {
        int n = graph.Length;
        int[] outDegree = new int[n];
        List<int>[] reverse = new List<int>[n];

        for (int i = 0; i < n; i++) {
            reverse[i] = new List<int>();
            outDegree[i] = graph[i].Length;

            foreach (int neighbor in graph[i]) {
                reverse[neighbor].Add(i);
            }
        }

        Queue<int> queue = new Queue<int>();

        for (int i = 0; i < n; i++) {
            if (outDegree[i] == 0) {
                queue.Enqueue(i);
            }
        }

        List<int> safeNodes = new List<int>();

        while (queue.Count > 0) {
            int node = queue.Dequeue();
            safeNodes.Add(node);

            foreach (int predecessor in reverse[node]) {
                outDegree[predecessor]--;

                if (outDegree[predecessor] == 0) {
                    queue.Enqueue(predecessor);
                }
            }
        }

        safeNodes.Sort();
        return safeNodes;
    }
}
