using System;

public class Solution
{
    public long MaximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial)
    {
        int n = flowers.Length;

        for (int i = 0; i < n; i++)
        {
            if (flowers[i] > target)
                flowers[i] = target;
        }

        Array.Sort(flowers);

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++)
            prefix[i + 1] = prefix[i] + flowers[i];

        int alreadyComplete = 0;
        while (alreadyComplete < n && flowers[alreadyComplete] < target)
            alreadyComplete++;

        long answer = 0;

        for (int complete = alreadyComplete; complete <= n; complete++)
        {
            long fullCost = (long)complete * target
                            - (prefix[n] - prefix[n - complete]);

            if (fullCost > newFlowers)
                continue;

            long remaining = newFlowers - fullCost;
            int incomplete = n - complete;

            long beauty;

            if (incomplete == 0)
            {
                beauty = (long)complete * full;
            }
            else
            {
                int low = 0;
                int high = target - 1;
                int bestLevel = 0;

                while (low <= high)
                {
                    int mid = low + (high - low) / 2;

                    int left = 0;
                    int right = incomplete;

                    while (left < right)
                    {
                        int middle = left + (right - left) / 2;
                        if (flowers[middle] < mid)
                            left = middle + 1;
                        else
                            right = middle;
                    }

                    long cost = (long)mid * left - prefix[left];

                    if (cost <= remaining)
                    {
                        bestLevel = mid;
                        low = mid + 1;
                    }
                    else
                    {
                        high = mid - 1;
                    }
                }

                beauty = (long)complete * full
                         + (long)bestLevel * partial;
            }

            if (beauty > answer)
                answer = beauty;
        }

        return answer;
    }
}
