public class Solution
{
    private readonly Dictionary<int, int> memo = new Dictionary<int, int>();

    public int MinDays(int n)
    {
        if (n == 0)
            return 0;

        if (memo.TryGetValue(n, out int days))
            return days;

        int byTwo = n % 2 + 1 + MinDays(n / 2);
        int byThree = n % 3 + 1 + MinDays(n / 3);

        days = byTwo < byThree ? byTwo : byThree;
        memo[n] = days;

        return days;
    }
}
