public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int size = 1 << n;
        int[] sessions = new int[size];
        int[] remaining = new int[size];

        for (int mask = 0; mask < size; mask++) {
            sessions[mask] = int.MaxValue;
        }

        sessions[0] = 0;
        remaining[0] = sessionTime;

        for (int mask = 0; mask < size; mask++) {
            if (sessions[mask] == int.MaxValue) {
                continue;
            }

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                int nextMask = mask | (1 << i);
                int nextSessions;
                int nextRemaining;

                if (tasks[i] <= remaining[mask]) {
                    nextSessions = sessions[mask];
                    nextRemaining = remaining[mask] - tasks[i];
                } else {
                    nextSessions = sessions[mask] + 1;
                    nextRemaining = sessionTime - tasks[i];
                }

                if (nextSessions < sessions[nextMask] ||
                    (nextSessions == sessions[nextMask] &&
                     nextRemaining > remaining[nextMask])) {
                    sessions[nextMask] = nextSessions;
                    remaining[nextMask] = nextRemaining;
                }
            }
        }

        return sessions[size - 1];
    }
}
