using System;
using System.Collections.Generic;

public class Solution
{
    private struct Item
    {
        public int Value;
        public int Index;

        public Item(int value, int index)
        {
            Value = value;
            Index = index;
        }
    }

    private class ItemComparer : IComparer<Item>
    {
        public int Compare(Item x, Item y)
        {
            int result = x.Value.CompareTo(y.Value);
            return result != 0 ? result : x.Index.CompareTo(y.Index);
        }
    }

    public double[] MedianSlidingWindow(int[] nums, int k)
    {
        int n = nums.Length;
        double[] result = new double[n - k + 1];

        var comparer = new ItemComparer();
        var low = new SortedSet<Item>(comparer);
        var high = new SortedSet<Item>(comparer);

        int targetLowSize = (k + 1) / 2;

        void Rebalance()
        {
            while (low.Count > targetLowSize)
            {
                Item item = low.Max;
                low.Remove(item);
                high.Add(item);
            }

            while (low.Count < targetLowSize)
            {
                Item item = high.Min;
                high.Remove(item);
                low.Add(item);
            }
        }

        void Add(Item item)
        {
            if (low.Count == 0 || comparer.Compare(item, low.Max) <= 0)
                low.Add(item);
            else
                high.Add(item);

            Rebalance();
        }

        void Remove(Item item)
        {
            if (!low.Remove(item))
                high.Remove(item);

            Rebalance();
        }

        for (int i = 0; i < k; i++)
            Add(new Item(nums[i], i));

        for (int start = 0; start <= n - k; start++)
        {
            if ((k & 1) == 1)
            {
                result[start] = low.Max.Value;
            }
            else
            {
                result[start] = ((double)low.Max.Value + high.Min.Value) / 2.0;
            }

            if (start + k < n)
            {
                Remove(new Item(nums[start], start));
                Add(new Item(nums[start + k], start + k));
            }
        }

        return result;
    }
}
