public class StreamChecker
{
    private readonly int[] _next;
    private readonly bool[] _terminal;
    private readonly int _maxWordLength;
    private char[] _stream;
    private int _streamLength;
    private int _nodeCount;

    public StreamChecker(string[] words)
    {
        int totalLength = 0;
        _maxWordLength = 0;

        foreach (string word in words)
        {
            totalLength += word.Length;
            if (word.Length > _maxWordLength)
                _maxWordLength = word.Length;
        }

        _next = new int[(totalLength + 1) * 26];
        _terminal = new bool[totalLength + 1];
        _stream = new char[40000];
        _nodeCount = 1;

        foreach (string word in words)
        {
            int node = 0;

            for (int i = word.Length - 1; i >= 0; i--)
            {
                int index = word[i] - 'a';
                int nextNode = _next[node * 26 + index];

                if (nextNode == 0)
                {
                    nextNode = _nodeCount++;
                    _next[node * 26 + index] = nextNode;
                }

                node = nextNode;
            }

            _terminal[node] = true;
        }
    }

    public bool Query(char letter)
    {
        if (_streamLength == _stream.Length)
        {
            char[] expanded = new char[_stream.Length * 2];
            System.Array.Copy(_stream, expanded, _stream.Length);
            _stream = expanded;
        }

        _stream[_streamLength++] = letter;

        int node = 0;
        int start = _streamLength - 1;
        int limit = _streamLength - _maxWordLength;

        for (int i = start; i >= limit; i--)
        {
            int index = _stream[i] - 'a';
            node = _next[node * 26 + index];

            if (node == 0)
                return false;

            if (_terminal[node])
                return true;
        }

        return false;
    }
}
