using System.Collections.Generic;

public class Solution
{
    public IList<string> AmbiguousCoordinates(string s)
    {
        string digits = s.Substring(1, s.Length - 2);
        var result = new List<string>();

        for (int split = 1; split < digits.Length; split++)
        {
            string left = digits.Substring(0, split);
            string right = digits.Substring(split);

            List<string> leftOptions = Formats(left);
            List<string> rightOptions = Formats(right);

            foreach (string x in leftOptions)
            {
                foreach (string y in rightOptions)
                {
                    result.Add("(" + x + ", " + y + ")");
                }
            }
        }

        return result;
    }

    private List<string> Formats(string value)
    {
        var result = new List<string>();

        if (value == "0" || value[0] != '0')
        {
            result.Add(value);
        }

        for (int i = 1; i < value.Length; i++)
        {
            string integerPart = value.Substring(0, i);
            string fractionalPart = value.Substring(i);

            if (integerPart[0] == '0' && integerPart.Length > 1)
            {
                continue;
            }

            if (fractionalPart[fractionalPart.Length - 1] == '0')
            {
                continue;
            }

            result.Add(integerPart + "." + fractionalPart);
        }

        return result;
    }
}
