public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        const long MOD = 1000000007L;

        Array.Sort(arr);
        int n = arr.Length;
        long[] dp = new long[n];
        var index = new Dictionary<int, int>();

        for (int i = 0; i < n; i++) {
            index[arr[i]] = i;
        }

        long total = 0;

        for (int i = 0; i < n; i++) {
            dp[i] = 1;

            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int right = arr[i] / arr[j];

                    if (index.TryGetValue(right, out int k)) {
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                    }
                }
            }

            total = (total + dp[i]) % MOD;
        }

        return (int)total;
    }
}
