using System;

public class Solution
{
    private class UnionFind
    {
        private readonly int[] parent;
        private readonly int[] size;

        public UnionFind(int count)
        {
            parent = new int[count];
            size = new int[count];

            for (int i = 0; i < count; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            if (parent[x] != x)
                parent[x] = Find(parent[x]);

            return parent[x];
        }

        public void Union(int a, int b)
        {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB)
                return;

            if (size[rootA] < size[rootB])
            {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        public int ComponentSize(int x)
        {
            return size[Find(x)];
        }
    }

    public int[] HitBricks(int[][] grid, int[][] hits)
    {
        int m = grid.Length;
        int n = grid[0].Length;
        int total = m * n;
        int top = total;

        bool[] removedBricks = new bool[hits.Length];

        for (int i = 0; i < hits.Length; i++)
        {
            int r = hits[i][0];
            int c = hits[i][1];

            if (grid[r][c] == 1)
            {
                removedBricks[i] = true;
                grid[r][c] = 0;
            }
        }

        UnionFind uf = new UnionFind(total + 1);
        bool[] active = new bool[total + 1];

        for (int r = 0; r < m; r++)
        {
            for (int c = 0; c < n; c++)
            {
                if (grid[r][c] == 0)
                    continue;

                int id = r * n + c;
                active[id] = true;

                if (r == 0)
                    uf.Union(id, top);

                if (r > 0 && grid[r - 1][c] == 1)
                    uf.Union(id, (r - 1) * n + c);

                if (c > 0 && grid[r][c - 1] == 1)
                    uf.Union(id, r * n + c - 1);
            }
        }

        int[] result = new int[hits.Length];
        int[][] directions =
        {
            new[] { -1, 0 },
            new[] { 1, 0 },
            new[] { 0, -1 },
            new[] { 0, 1 }
        };

        for (int i = hits.Length - 1; i >= 0; i--)
        {
            if (!removedBricks[i])
                continue;

            int r = hits[i][0];
            int c = hits[i][1];
            int id = r * n + c;

            int before = uf.ComponentSize(top);

            active[id] = true;
            grid[r][c] = 1;

            if (r == 0)
                uf.Union(id, top);

            for (int d = 0; d < 4; d++)
            {
                int nr = r + directions[d][0];
                int nc = c + directions[d][1];

                if (nr < 0 || nr >= m || nc < 0 || nc >= n)
                    continue;

                int neighbor = nr * n + nc;
                if (active[neighbor])
                    uf.Union(id, neighbor);
            }

            int after = uf.ComponentSize(top);
            result[i] = Math.Max(0, after - before - 1);
        }

        return result;
    }
}
