public class Solution {
    public bool AreOccurrencesEqual(string s) {
        int[] counts = new int[26];

        foreach (char c in s) {
            counts[c - 'a']++;
        }

        int expected = 0;

        foreach (int count in counts) {
            if (count == 0) {
                continue;
            }

            if (expected == 0) {
                expected = count;
            } else if (count != expected) {
                return false;
            }
        }

        return true;
    }
}
