public class Solution {
    public int Clumsy(int n) {
        Stack<int> stack = new Stack<int>();
        stack.Push(n);

        int operation = 0;

        for (int value = n - 1; value >= 1; value--) {
            if (operation == 0) {
                int previous = stack.Pop();
                stack.Push(previous * value);
            } else if (operation == 1) {
                int previous = stack.Pop();
                stack.Push(previous / value);
            } else if (operation == 2) {
                stack.Push(value);
            } else {
                stack.Push(-value);
            }

            operation = (operation + 1) % 4;
        }

        int result = 0;
        while (stack.Count > 0) {
            result += stack.Pop();
        }

        return result;
    }
}
