public class Solution
{
    public int[] NumSmallerByFrequency(string[] queries, string[] words)
    {
        int[] wordFrequencies = new int[words.Length];

        for (int i = 0; i < words.Length; i++)
        {
            wordFrequencies[i] = Frequency(words[i]);
        }

        Array.Sort(wordFrequencies);

        int[] answer = new int[queries.Length];

        for (int i = 0; i < queries.Length; i++)
        {
            int queryFrequency = Frequency(queries[i]);
            int firstGreater = UpperBound(wordFrequencies, queryFrequency);
            answer[i] = wordFrequencies.Length - firstGreater;
        }

        return answer;
    }

    private int Frequency(string s)
    {
        char smallest = s[0];
        int count = 1;

        for (int i = 1; i < s.Length; i++)
        {
            if (s[i] < smallest)
            {
                smallest = s[i];
                count = 1;
            }
            else if (s[i] == smallest)
            {
                count++;
            }
        }

        return count;
    }

    private int UpperBound(int[] array, int value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;

            if (array[middle] <= value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }
}
