using System;
using System.Collections.Generic;

public class MKAverage
{
    private class MultiSet
    {
        private readonly SortedDictionary<int, int> counts = new SortedDictionary<int, int>();
        private readonly SortedSet<int> keys = new SortedSet<int>();

        public int Count { get; private set; }
        public long Sum { get; private set; }

        public void Add(int value)
        {
            if (counts.ContainsKey(value))
                counts[value]++;
            else
            {
                counts[value] = 1;
                keys.Add(value);
            }

            Count++;
            Sum += value;
        }

        public void Remove(int value)
        {
            counts[value]--;

            if (counts[value] == 0)
            {
                counts.Remove(value);
                keys.Remove(value);
            }

            Count--;
            Sum -= value;
        }

        public int Min => keys.Min;
        public int Max => keys.Max;
    }

    private readonly int m;
    private readonly int k;
    private readonly Queue<int> window = new Queue<int>();

    private readonly MultiSet low = new MultiSet();
    private readonly MultiSet middle = new MultiSet();
    private readonly MultiSet high = new MultiSet();

    private bool initialized;

    public MKAverage(int m, int k)
    {
        this.m = m;
        this.k = k;
    }

    public void AddElement(int num)
    {
        if (window.Count == m)
        {
            int removed = window.Dequeue();
            RemoveFromSets(removed);
        }

        window.Enqueue(num);

        if (window.Count < m)
            return;

        if (!initialized)
        {
            foreach (int value in window)
                middle.Add(value);

            initialized = true;
        }
        else
        {
            middle.Add(num);
        }

        Normalize();
    }

    public int CalculateMKAverage()
    {
        if (window.Count < m)
            return -1;

        return (int)(middle.Sum / (m - 2L * k));
    }

    private void RemoveFromSets(int value)
    {
        if (low.Count > 0 && Contains(low, value))
            low.Remove(value);
        else if (middle.Count > 0 && Contains(middle, value))
            middle.Remove(value);
        else
            high.Remove(value);
    }

    private bool Contains(MultiSet set, int value)
    {
        if (set.Count == 0)
            return false;

        if (value < set.Min || value > set.Max)
            return false;

        return true;
    }

    private void Normalize()
    {
        while (low.Count > k)
            MoveMax(low, middle);

        while (high.Count > k)
            MoveMin(high, middle);

        while (low.Count < k)
            MoveMin(middle, low);

        while (high.Count < k)
            MoveMax(middle, high);

        while (true)
        {
            bool changed = false;

            if (low.Count > 0 && middle.Count > 0 && low.Max > middle.Min)
            {
                int a = low.Max;
                int b = middle.Min;

                low.Remove(a);
                middle.Remove(b);
                low.Add(b);
                middle.Add(a);

                changed = true;
            }

            if (middle.Count > 0 && high.Count > 0 && middle.Max > high.Min)
            {
                int a = middle.Max;
                int b = high.Min;

                middle.Remove(a);
                high.Remove(b);
                middle.Add(b);
                high.Add(a);

                changed = true;
            }

            if (!changed)
                break;
        }
    }

    private void MoveMin(MultiSet from, MultiSet to)
    {
        int value = from.Min;
        from.Remove(value);
        to.Add(value);
    }

    private void MoveMax(MultiSet from, MultiSet to)
    {
        int value = from.Max;
        from.Remove(value);
        to.Add(value);
    }
}
