public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        if (n == 2)
            return stones[1] == 1;

        if (stones[1] != 1)
            return false;

        var positionToIndex = new Dictionary<int, int>();
        for (int i = 0; i < n; i++)
            positionToIndex[stones[i]] = i;

        var reachableJumps = new HashSet<int>[n];
        for (int i = 0; i < n; i++)
            reachableJumps[i] = new HashSet<int>();

        reachableJumps[1].Add(1);

        for (int i = 1; i < n; i++) {
            foreach (int jump in reachableJumps[i]) {
                for (int delta = -1; delta <= 1; delta++) {
                    long nextJump = (long)jump + delta;
                    if (nextJump <= 0)
                        continue;

                    long nextPosition = (long)stones[i] + nextJump;
                    if (nextPosition > int.MaxValue)
                        continue;

                    if (positionToIndex.TryGetValue((int)nextPosition, out int nextIndex)) {
                        if (nextIndex == n - 1)
                            return true;

                        reachableJumps[nextIndex].Add((int)nextJump);
                    }
                }
            }
        }

        return false;
    }
}
