using System.Text;

public class Solution {
    public string LicenseKeyFormatting(string s, int k) {
        StringBuilder characters = new StringBuilder();

        foreach (char c in s) {
            if (c == '-') {
                continue;
            }

            characters.Append(c >= 'a' && c <= 'z'
                ? (char)(c - 'a' + 'A')
                : c);
        }

        if (characters.Length == 0) {
            return string.Empty;
        }

        int firstGroupLength = characters.Length % k;
        if (firstGroupLength == 0) {
            firstGroupLength = k;
        }

        StringBuilder result = new StringBuilder();
        int index = 0;

        result.Append(characters.ToString(0, firstGroupLength));
        index = firstGroupLength;

        while (index < characters.Length) {
            result.Append('-');
            result.Append(characters.ToString(index, Math.Min(k, characters.Length - index)));
            index += k;
        }

        return result.ToString();
    }
}
