public class Solution {
    public int LengthOfLIS(int[] nums) {
        int[] tails = new int[nums.Length];
        int length = 0;

        foreach (int num in nums) {
            int left = 0;
            int right = length;

            while (left < right) {
                int mid = left + (right - left) / 2;

                if (tails[mid] < num)
                    left = mid + 1;
                else
                    right = mid;
            }

            tails[left] = num;

            if (left == length)
                length++;
        }

        return length;
    }
