using System.Collections.Generic;

public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) {
            return n;
        }

        int result = 1;

        for (int i = 0; i < n; i++) {
            var slopes = new Dictionary<(int, int), int>();
            int best = 0;

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                if (dx == 0) {
                    dy = 1;
                } else if (dy == 0) {
                    dx = 1;
                } else {
                    int divisor = Gcd(Math.Abs(dx), Math.Abs(dy));
                    dx /= divisor;
                    dy /= divisor;

                    if (dx < 0) {
                        dx = -dx;
                        dy = -dy;
                    }
                }

                var slope = (dy, dx);
                if (!slopes.ContainsKey(slope)) {
                    slopes[slope] = 0;
                }

                slopes[slope]++;
                best = Math.Max(best, slopes[slope]);
            }

            result = Math.Max(result, best + 1);
        }

        return result;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }

        return a;
    }
}
