using System;

public class Solution {
    public int MaxScore(int[] nums) {
        int m = nums.Length;
        int fullMask = (1 << m) - 1;
        int[] dp = new int[1 << m];
        Array.Fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] < 0) continue;

            int used = CountBits(mask);
            if (used == m) continue;

            int operation = used / 2 + 1;

            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) continue;

                for (int j = i + 1; j < m; j++) {
                    if ((mask & (1 << j)) != 0) continue;

                    int nextMask = mask | (1 << i) | (1 << j);
                    int score = dp[mask] + operation * Gcd(nums[i], nums[j]);

                    if (score > dp[nextMask]) {
                        dp[nextMask] = score;
                    }
                }
            }
        }

        return dp[fullMask];
    }

    private int CountBits(int value) {
        int count = 0;
        while (value != 0) {
            value &= value - 1;
            count++;
        }
        return count;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
