public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int stateCount = 1;
        for (int i = 0; i < numSlots; i++) {
            stateCount *= 3;
        }

        int[] powers = new int[numSlots];
        powers[0] = 1;
        for (int i = 1; i < numSlots; i++) {
            powers[i] = powers[i - 1] * 3;
        }

        int[] memo = new int[stateCount];
        for (int i = 0; i < stateCount; i++) {
            memo[i] = -1;
        }

        return Dp(0);

        int Dp(int state) {
            if (memo[state] != -1) {
                return memo[state];
            }

            int placed = 0;
            int temp = state;
            for (int i = 0; i < numSlots; i++) {
                placed += temp % 3;
                temp /= 3;
            }

            if (placed == nums.Length) {
                return memo[state] = 0;
            }

            int best = 0;

            for (int slot = 0; slot < numSlots; slot++) {
                int count = (state / powers[slot]) % 3;

                if (count < 2) {
                    int nextState = state + powers[slot];
                    int value = (nums[placed] & (slot + 1)) + Dp(nextState);
                    if (value > best) {
                        best = value;
                    }
                }
            }

            return memo[state] = best;
        }
    }
}
