public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int[,] scores = new int[m, m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int score = 0;
                for (int k = 0; k < students[i].Length; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        score++;
                    }
                }
                scores[i, j] = score;
            }
        }

        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];

        for (int mask = 1; mask < totalMasks; mask++) {
            dp[mask] = -1;
        }

        for (int mask = 0; mask < totalMasks; mask++) {
            int student = 0;
            int temp = mask;

            while (temp != 0) {
                student += temp & 1;
                temp >>= 1;
            }

            if (student >= m) {
                continue;
            }

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    int value = dp[mask] + scores[student, mentor];

                    if (value > dp[nextMask]) {
                        dp[nextMask] = value;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }
}
