public class Solution {
    public int MaxEqualFreq(int[] nums) {
        int n = nums.Length;
        int[] valueFrequency = new int[100001];
        int[] frequencyCount = new int[n + 1];

        int maxFrequency = 0;
        int distinct = 0;
        int answer = 0;

        for (int i = 0; i < n; i++) {
            int value = nums[i];
            int oldFrequency = valueFrequency[value];

            if (oldFrequency > 0) {
                frequencyCount[oldFrequency]--;
            } else {
                distinct++;
            }

            int newFrequency = ++valueFrequency[value];
            frequencyCount[newFrequency]++;

            if (newFrequency > maxFrequency) {
                maxFrequency = newFrequency;
            }

            bool valid =
                maxFrequency == 1 ||
                (frequencyCount[maxFrequency] == 1 &&
                 frequencyCount[maxFrequency - 1] == distinct - 1) ||
                (frequencyCount[1] == 1 &&
                 frequencyCount[maxFrequency] == distinct - 1);

            if (valid) {
                answer = i + 1;
            }
        }

        return answer;
    }
}
