public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int left = 0;
        long sum = 0;
        long answer = 0;

        for (int right = 0; right < fruits.Length; right++) {
            sum += fruits[right][1];

            while (left <= right && TravelCost(fruits[left][0], fruits[right][0], startPos) > k) {
                sum -= fruits[left][1];
                left++;
            }

            if (sum > answer) {
                answer = sum;
            }
        }

        return (int)answer;
    }

    private long TravelCost(int left, int right, int startPos) {
        if (right < startPos) {
            return (long)startPos - left;
        }

        if (left > startPos) {
            return (long)right - startPos;
        }

        long goLeftFirst = 2L * (startPos - left) + (right - startPos);
        long goRightFirst = 2L * (right - startPos) + (startPos - left);

        return Math.Min(goLeftFirst, goRightFirst);
    }
}
