public class Solution {
    public long MaxRunTime(int n, int[] batteries) {
        long total = 0;
        foreach (int battery in batteries) {
            total += battery;
        }

        long low = 0;
        long high = total / n;

        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            long available = 0;

            foreach (int battery in batteries) {
                available += Math.Min((long)battery, mid);
                if (available >= mid * n) {
                    break;
                }
            }

            if (available >= mid * n) {
