public class Solution {
    public int MaxStudents(char[][] seats) {
        int m = seats.Length;
        int n = seats[0].Length;
        int totalMasks = 1 << n;

        bool[] valid = new bool[totalMasks];
        int[] bitCount = new int[totalMasks];

        for (int mask = 0; mask < totalMasks; mask++) {
            valid[mask] = (mask & (mask << 1)) == 0;
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
        }

        int[] dp = new int[totalMasks];
        for (int i = 0; i < totalMasks; i++) {
            dp[i] = -1000000;
        }
        dp[0] = 0;

        for (int row = 0; row < m; row++) {
            int available = 0;
            for (int col = 0; col < n; col++) {
                if (seats[row][col] == '.') {
                    available |= 1 << col;
                }
            }

            int[] next = new int[totalMasks];
            for (int i = 0; i < totalMasks; i++) {
                next[i] = -1000000;
            }

            for (int current = 0; current < totalMasks; current++) {
                if (!valid[current] || (current & ~available) != 0) {
                    continue;
                }

                for (int previous = 0; previous < totalMasks; previous++) {
                    if ((current & (previous << 1)) != 0 ||
                        (current & (previous >> 1)) != 0) {
                        continue;
                    }

                    next[current] = System.Math.Max(
                        next[current],
                        dp[previous] + bitCount[current]
                    );
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int mask = 0; mask < totalMasks; mask++) {
            answer = System.Math.Max(answer, dp[mask]);
        }

        return answer;
    }
}
