    public int MaxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.Length;
        int[] prefix = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int result = Math.Max(
            GetMaxOrder(prefix, n, firstLen, secondLen),
            GetMaxOrder(prefix, n, secondLen, firstLen)
        );

