    private int GetMaxOrder(int[] prefix, int n, int leftLen, int rightLen) {
        int maxLeft = 0;
        int result = 0;

        for (int split = leftLen; split <= n - rightLen; split++) {
            int leftSum = prefix[split] - prefix[split - leftLen];
            maxLeft = Math.Max(maxLeft, leftSum);

            int rightSum = prefix[split + rightLen] - prefix[split];
            result = Math.Max(result, maxLeft + rightSum);
        }

        return result;
    }
