public class Solution {
    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        bool[] isInitial = new bool[n];

        foreach (int node in initial) {
            isInitial[node] = true;
        }

        int[] component = new int[n];
        Array.Fill(component, -1);

        var sizes = new System.Collections.Generic.List<int>();
        int componentCount = 0;

        for (int i = 0; i < n; i++) {
            if (isInitial[i] || component[i] != -1) {
                continue;
            }

            int size = 0;
            var queue = new System.Collections.Generic.Queue<int>();
            queue.Enqueue(i);
            component[i] = componentCount;

            while (queue.Count > 0) {
                int node = queue.Dequeue();
                size++;

                for (int next = 0; next < n; next++) {
                    if (!isInitial[next] &&
                        component[next] == -1 &&
                        graph[node][next] == 1) {
                        component[next] = componentCount;
                        queue.Enqueue(next);
                    }
                }
            }

            sizes.Add(size);
            componentCount++;
        }

        int[] owner = new int[componentCount];
        bool[] multiple = new bool[componentCount];
        Array.Fill(owner, -1);

        foreach (int source in initial) {
            for (int node = 0; node < n; node++) {
                if (graph[source][node] == 1 && !isInitial[node]) {
                    int comp = component[node];

                    if (owner[comp] == -1) {
                        owner[comp] = source;
                    } else if (owner[comp] != source) {
                        multiple[comp] = true;
                    }
                }
            }
        }

        int bestNode = int.MaxValue;
        int bestSaved = -1;

        foreach (int source in initial) {
            int saved = 0;

            for (int comp = 0; comp < componentCount; comp++) {
                if (!multiple[comp] && owner[comp] == source) {
                    saved += sizes[comp];
                }
            }

            if (saved > bestSaved || (saved == bestSaved && source < bestNode)) {
                bestSaved = saved;
                bestNode = source;
            }
        }

        return bestNode;
    }
}
