public class Solution {
    public int MinCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.Length;
        const int INF = int.MaxValue / 2;

        int[,] dp = new int[maxTime + 1, n];

        for (int time = 0; time <= maxTime; time++) {
            for (int city = 0; city < n; city++) {
                dp[time, city] = INF;
            }
        }

        dp[0, 0] = passingFees[0];

        for (int time = 0; time <= maxTime; time++) {
            for (int i = 0; i < edges.Length; i++) {
                int from = edges[i][0];
                int to = edges[i][1];
                int travelTime = edges[i][2];

                if (time + travelTime > maxTime) {
                    continue;
                }

                if (dp[time, from] != INF) {
                    int cost = dp[time, from] + passingFees[to];
                    if (cost < dp[time + travelTime, to]) {
                        dp[time + travelTime, to] = cost;
                    }
                }

                if (dp[time, to] != INF) {
                    int cost = dp[time, to] + passingFees[from];
                    if (cost < dp[time + travelTime, from]) {
                        dp[time + travelTime, from] = cost;
                    }
                }
            }
        }

        int result = INF;
        for (int time = 0; time <= maxTime; time++) {
            if (dp[time, n - 1] < result) {
                result = dp[time, n - 1];
            }
        }

        return result == INF ? -1 : result;
    }
}
