public class Solution {
    public int MinDays(int[][] grid) {
        int initialIslands = CountIslands(grid);

        if (initialIslands != 1) {
            return 0;
        }

        int m = grid.Length;
        int n = grid[0].Length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;

                    if (CountIslands(grid) != 1) {
                        return 1;
                    }

                    grid[i][j] = 1;
                }
            }
        }

        return 2;
    }

    private int CountIslands(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        bool[][] visited = new bool[m][];

        for (int i = 0; i < m; i++) {
            visited[i] = new bool[n];
        }

        int islands = 0;
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    islands++;
                    if (islands > 1) {
                        return islands;
                    }

                    Queue<int> queue = new Queue<int>();
                    queue.Enqueue(r * n + c);
                    visited[r][c] = true;

                    while (queue.Count > 0) {
                        int cell = queue.Dequeue();
                        int cr = cell / n;
                        int cc = cell % n;

                        for (int k = 0; k < 4; k++) {
                            int nr = cr + dr[k];
                            int nc = cc + dc[k];

                            if (nr >= 0 && nr < m &&
                                nc >= 0 && nc < n &&
                                grid[nr][nc] == 1 &&
                                !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                queue.Enqueue(nr * n + nc);
                            }
                        }
                    }
                }
            }
        }

        return islands;
    }
}
