public class Solution {
    public int NextBeautifulNumber(int n) {
        List<int> numbers = new List<int>();

        for (int mask = 1; mask < (1 << 7); mask++) {
            int totalDigits = 0;
            int[] counts = new int[8];

            for (int d = 1; d <= 7; d++) {
                if ((mask & (1 << (d - 1))) != 0) {
                    counts[d] = d;
                    totalDigits += d;
                }
            }

            if (totalDigits > 7) {
                continue;
            }

            void Generate(int value, int remaining) {
                if (remaining == 0) {
                    numbers.Add(value);
                    return;
                }

                for (int d = 1; d <= 7; d++) {
                    if (counts[d] > 0) {
                        counts[d]--;
                        Generate(value * 10 + d, remaining - 1);
                        counts[d]++;
                    }
                }
            }

            Generate(0, totalDigits);
        }

        numbers.Sort();

        int left = 0;
        int right = numbers.Count - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (numbers[mid] <= n) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return numbers[left];
    }
}
