using System;
using System.Collections.Generic;

public class Solution {
    private const long MOD = 1000000007;
    private long[] factorial;
    private long[] inverseFactorial;

    public int NumOfWays(int[] nums) {
        int n = nums.Length;
        factorial = new long[n + 1];
        inverseFactorial = new long[n + 1];

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }

        inverseFactorial[n] = ModPow(factorial[n], MOD - 2);
        for (int i = n; i >= 1; i--) {
            inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD;
        }

        var values = new List<int>(nums);
        long result = CountWays(values) - 1;
        if (result < 0) result += MOD;

        return (int)result;
    }

    private long CountWays(List<int> values) {
        if (values.Count <= 2) return 1;

        int root = values[0];
        var left = new List<int>();
        var right = new List<int>();

        for (int i = 1; i < values.Count; i++) {
            if (values[i] < root) {
                left.Add(values[i]);
            } else {
                right.Add(values[i]);
            }
        }

        long combinations = Combination(values.Count - 1, left.Count);
        long leftWays = CountWays(left);
        long rightWays = CountWays(right);

        return combinations * leftWays % MOD * rightWays % MOD;
    }

    private long Combination(int n, int k) {
        return factorial[n] * inverseFactorial[k] % MOD * inverseFactorial[n - k] % MOD;
    }

    private long ModPow(long value, long exponent) {
        long result = 1;

        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = result * value % MOD;
            }

            value = value * value % MOD;
            exponent >>= 1;
        }

        return result;
    }
}
