public class Solution {
    public int NumTriplets(int[] nums1, int[] nums2) {
        long result = Count(nums1, nums2) + Count(nums2, nums1);
        return (int)result;
    }

    private long Count(int[] targets, int[] values) {
        var pairProducts = new Dictionary<long, int>();

        for (int i = 0; i < values.Length; i++) {
            for (int j = i + 1; j < values.Length; j++) {
                long product = (long)values[i] * values[j];

                if (pairProducts.ContainsKey(product)) {
                    pairProducts[product]++;
                } else {
                    pairProducts[product] = 1;
                }
            }
        }

        long count = 0;

        foreach (int value in targets) {
            long square = (long)value * value;

            if (pairProducts.TryGetValue(square, out int frequency)) {
                count += frequency;
            }
        }

        return count;
    }
}
