public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        foreach (int num in nums) {
            total += num;
        }

        if (total % k != 0) {
            return false;
        }

        int target = total / k;

        Array.Sort(nums);
        Array.Reverse(nums);

        if (nums[0] > target) {
            return false;
        }

        int n = nums.Length;
        int size = 1 << n;
        int[] dp = new int[size];
        Array.Fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            int current = dp[mask];

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                if (current + nums[i] > target) {
                    continue;
                }

                int nextMask = mask | (1 << i);
                if (dp[nextMask] == -1) {
                    dp[nextMask] = (current + nums[i]) % target;
                }
            }
        }

        return dp[size - 1] == 0;
    }
}
