public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int n = slices.Length / 3;

        int option1 = SolveRange(slices, 0, slices.Length - 2, n);
        int option2 = SolveRange(slices, 1, slices.Length - 1, n);

        return Math.Max(option1, option2);
    }

    private int SolveRange(int[] slices, int start, int end, int picks) {
        int count = end - start + 1;
        const int NEGATIVE = -1000000000;

        int[,] dp = new int[count + 1, picks + 1];

        for (int i = 0; i <= count; i++) {
            for (int j = 0; j <= picks; j++) {
                dp[i, j] = NEGATIVE;
            }
        }

        dp[0, 0] = 0;

        for (int i = 1; i <= count; i++) {
            dp[i, 0] = 0;

            for (int j = 1; j <= picks; j++) {
                dp[i, j] = dp[i - 1, j];

                int previous = i == 1 ? dp[0, j - 1] : dp[i - 2, j - 1];
                if (previous != NEGATIVE) {
                    dp[i, j] = Math.Max(
                        dp[i, j],
                        previous + slices[start + i - 1]
                    );
                }
            }
        }

        return dp[count, picks];
    }
}
