public class Solution {
    private int[] parent;
    private int[] rank;

    public bool[] FriendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        bool[] result = new bool[requests.Length];

        for (int i = 0; i < requests.Length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];

            int rootU = Find(u);
            int rootV = Find(v);

            if (rootU == rootV) {
                result[i] = true;
                continue;
            }

            bool allowed = true;

            foreach (int[] restriction in restrictions) {
                int rootX = Find(restriction[0]);
                int rootY = Find(restriction[1]);

                if ((rootX == rootU && rootY == rootV) ||
                    (rootX == rootV && rootY == rootU)) {
                    allowed = false;
                    break;
                }
            }

            if (allowed) {
                Union(rootU, rootV);
                result[i] = true;
            }
        }

        return result;
    }

    private int Find(int x) {
        if (parent[x] != x) {
            parent[x] = Find(parent[x]);
        }

        return parent[x];
    }

    private void Union(int a, int b) {
        a = Find(a);
        b = Find(b);

        if (a == b) {
            return;
        }

        if (rank[a] < rank[b]) {
            parent[a] = b;
        } else if (rank[a] > rank[b]) {
            parent[b] = a;
        } else {
            parent[b] = a;
            rank[a]++;
        }
    }
}
