public class Solution
{
    private class DisjointSet
    {
        private readonly int[] parent;
        private readonly int[] rank;

        public DisjointSet(int size)
        {
            parent = new int[size];
            rank = new int[size];

            for (int i = 0; i < size; i++)
                parent[i] = i;
        }

        public int Find(int x)
        {
            if (parent[x] != x)
                parent[x] = Find(parent[x]);

            return parent[x];
        }

        public void Union(int a, int b)
        {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB)
                return;

            if (rank[rootA] < rank[rootB])
                parent[rootA] = rootB;
            else if (rank[rootA] > rank[rootB])
                parent[rootB] = rootA;
            else
            {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }

    public int RegionsBySlashes(string[] grid)
    {
        int n = grid.Length;
        int total = n * n * 4;
        var dsu = new DisjointSet(total);

        int Id(int row, int col, int part)
        {
            return (row * n + col) * 4 + part;
        }

        for (int row = 0; row < n; row++)
        {
            for (int col = 0; col < n; col++)
            {
                char cell = grid[row][col];

                int top = Id(row, col, 0);
                int right = Id(row, col, 1);
                int bottom = Id(row, col, 2);
                int left = Id(row, col, 3);

                if (cell == ' ')
                {
                    dsu.Union(top, right);
                    dsu.Union(right, bottom);
                    dsu.Union(bottom, left);
                }
                else if (cell == '/')
                {
                    dsu.Union(top, left);
                    dsu.Union(right, bottom);
                }
                else
                {
                    dsu.Union(top, right);
                    dsu.Union(bottom, left);
                }

                if (row + 1 < n)
                    dsu.Union(bottom, Id(row + 1, col, 0));

                if (col + 1 < n)
                    dsu.Union(right, Id(row, col + 1, 3));
            }
        }

        int regions = 0;
        for (int i = 0; i < total; i++)
        {
            if (dsu.Find(i) == i)
                regions++;
        }

        return regions;
    }
}
