using System;
using System.Collections.Generic;

public class Solution
{
    private readonly List<string> result = new List<string>();

    public IList<string> RemoveInvalidParentheses(string s)
    {
        result.Clear();
        RemoveInvalid(s, 0, 0, '(', ')');
        return result;
    }

    private void RemoveInvalid(string s, int lastIndex, int lastRemoved, char open, char close)
    {
        int balance = 0;

        for (int i = lastIndex; i < s.Length; i++)
        {
            if (s[i] == open)
                balance++;
            else if (s[i] == close)
                balance--;

            if (balance >= 0)
                continue;

            for (int j = lastRemoved; j <= i; j++)
            {
                if (s[j] == close && (j == lastRemoved || s[j - 1] != close))
                {
                    RemoveInvalid(
                        s.Remove(j, 1),
                        i,
                        j,
                        open,
                        close
                    );
                }
            }

            return;
        }

        string reversed = Reverse(s);

        if (open == '(')
        {
            RemoveInvalid(reversed, 0, 0, ')', '(');
        }
        else
        {
            result.Add(reversed);
        }
    }

    private string Reverse(string s)
    {
        char[] chars = s.ToCharArray();
        Array.Reverse(chars);
        return new string(chars);
    }
}
