public class Solution {
    private string _s1;
    private string _s2;
    private int[,] _prefix1;
    private int[,] _prefix2;
    private byte[,,] _memo;

    public bool IsScramble(string s1, string s2) {
        if (s1.Length != s2.Length) {
            return false;
        }

        _s1 = s1;
        _s2 = s2;

        int n = s1.Length;
        _prefix1 = new int[n + 1, 26];
        _prefix2 = new int[n + 1, 26];

        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 26; c++) {
                _prefix1[i + 1, c] = _prefix1[i, c];
                _prefix2[i + 1, c] = _prefix2[i, c];
            }

            _prefix1[i + 1, s1[i] - 'a']++;
            _prefix2[i + 1, s2[i] - 'a']++;
        }

        _memo = new byte[n, n, n + 1];
        return Solve(0, 0, n);
    }

    private bool Solve(int start1, int start2, int length) {
        if (_memo[start1, start2, length] != 0) {
            return _memo[start1, start2, length] == 2;
        }

        if (!HaveSameCharacters(start1, start2, length)) {
            _memo[start1, start2, length] = 1;
            return false;
        }

        if (length == 1) {
            bool equal = _s1[start1] == _s2[start2];
            _memo[start1, start2, length] = equal ? (byte)2 : (byte)1;
            return equal;
        }

        for (int split = 1; split < length; split++) {
            bool withoutSwap =
                Solve(start1, start2, split) &&
                Solve(start1 + split, start2 + split, length - split);

            if (withoutSwap) {
                _memo[start1, start2, length] = 2;
                return true;
            }

            bool withSwap =
                Solve(start1, start2 + length - split, split) &&
                Solve(start1 + split, start2, length - split);

            if (withSwap) {
                _memo[start1, start2, length] = 2;
                return true;
            }
        }

        _memo[start1, start2, length] = 1;
        return false;
    }

    private bool HaveSameCharacters(int start1, int start2, int length) {
        for (int c = 0; c < 26; c++) {
            int count1 = _prefix1[start1 + length, c] - _prefix1[start1, c];
            int count2 = _prefix2[start2 + length, c] - _prefix2[start2, c];

            if (count1 != count2) {
                return false;
            }
        }

        return true;
    }
}
