                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result.Add(new[] { r, c });
                        if (result.Count == total) {
                            break;
                        }
                    }
                }

                direction = (direction + 1) % 4;
            }

            stepLength++;
        }

        return result.ToArray();
    }
