using System;

public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int m = target.Length;
        int n = stickers.Length;
        int[] targetChars = new int[m];

        for (int i = 0; i < m; i++) {
            targetChars[i] = target[i] - 'a';
        }

        int[][] counts = new int[n][];
        for (int i = 0; i < n; i++) {
            counts[i] = new int[26];
            foreach (char c in stickers[i]) {
                counts[i][c - 'a']++;
            }
        }

        int[] memo = new int[1 << m];
        for (int i = 0; i < memo.Length; i++) {
            memo[i] = -1;
        }

        int Dfs(int mask) {
            if (mask == (1 << m) - 1) {
                return 0;
            }

            if (memo[mask] != -1) {
                return memo[mask];
            }

            int best = int.MaxValue;

            for (int s = 0; s < n; s++) {
                int newMask = mask;

                for (int i = 0; i < m; i++) {
                    int bit = 1 << i;
                    int letter = targetChars[i];

                    if ((newMask & bit) == 0 && counts[s][letter] > 0) {
                        counts[s][letter]--;
                        newMask |= bit;
                    }
                }

                if (newMask != mask) {
                    for (int i = 0; i < m; i++) {
                        int bit = 1 << i;
                        if ((mask & bit) == 0 && (newMask & bit) != 0) {
                            counts[s][targetChars[i]]++;
                        }
                    }

                    int result = Dfs(newMask);
                    if (result != int.MaxValue) {
                        best = Math.Min(best, result + 1);
                    }
                }
            }

            memo[mask] = best;
            return best;
        }

        int answer = Dfs(0);
        return answer == int.MaxValue ? -1 : answer;
    }
}
