            bool endsWithAA = result.Length >= 2 &&
                              result[result.Length - 1] == 'a' &&
                              result[result.Length - 2] == 'a';

            bool endsWithBB = result.Length >= 2 &&
                              result[result.Length - 1] == 'b' &&
                              result[result.Length - 2] == 'b';

            if (endsWithAA) {
                result.Append('b');
                b--;
            } else if (endsWithBB) {
                result.Append('a');
                a--;
            } else if (a >= b && a > 0) {
                result.Append('a');
                a--;
            } else {
                result.Append('b');
                b--;
            }
        }

        return result.ToString();
    }
