public class Solution
{
    private Dictionary<int, int[]> memo;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer)
    {
        memo = new Dictionary<int, int[]>();
        return Solve(n, firstPlayer, secondPlayer);
    }

    private int[] Solve(int n, int a, int b)
    {
        int key = n * 10000 + a * 100 + b;

        if (memo.TryGetValue(key, out int[] cached))
            return cached;

        if (a + b == n + 1)
        {
            int[] result = { 1, 1 };
            memo[key] = result;
            return result;
        }

        HashSet<int> states = new HashSet<int>();
        states.Add(0);

        for (int i = 1; i <= n / 2; i++)
        {
            int left = i;
            int right = n + 1 - i;

            if (left == a || left == b || right == a || right == b)
                continue;

            int leftCategory = GetCategory(left, a, b);
            int rightCategory = GetCategory(right, a, b);

            HashSet<int> nextStates = new HashSet<int>();

            foreach (int state in states)
            {
                int x = state / 32;
                int y = state % 32;

                AddState(nextStates, x, y, leftCategory);
                AddState(nextStates, x, y, rightCategory);
            }

            states = nextStates;
        }

        if (n % 2 == 1)
        {
            int middle = (n + 1) / 2;

            if (middle != a && middle != b)
            {
                int category = GetCategory(middle, a, b);
                HashSet<int> nextStates = new HashSet<int>();

                foreach (int state in states)
                {
                    int x = state / 32;
                    int y = state % 32;
                    AddState(nextStates, x, y, category);
                }

                states = nextStates;
            }
        }

        int earliest = int.MaxValue;
        int latest = int.MinValue;
        int nextN = (n + 1) / 2;

        foreach (int state in states)
        {
            int x = state / 32;
            int y = state % 32;

            int nextA = x + 1;
            int nextB = x + y + 2;

            int[] child = Solve(nextN, nextA, nextB);

            earliest = Math.Min(earliest, child[0] + 1);
            latest = Math.Max(latest, child[1] + 1);
        }

        int[] answer = { earliest, latest };
        memo[key] = answer;
        return answer;
    }

    private int GetCategory(int player, int a, int b)
    {
        if (player < a)
            return 0;
        if (player < b)
            return 1;
        return 2;
    }

    private void AddState(HashSet<int> states, int x, int y, int category)
    {
        if (category == 0)
            x++;
        else if (category == 1)
            y++;

        states.Add(x * 32 + y);
    }
}
