        Array.Fill(answer, -1);

        var depth = new int[n];
        var nodesByValue = new Stack<int>[51];

        for (int i = 1; i <= 50; i++) {
            nodesByValue[i] = new Stack<int>();
        }

        var events = new Stack<(int node, int parent, bool exit)>();
        events.Push((0, -1, false));

        while (events.Count > 0) {
            var current = events.Pop();
            int node = current.node;
            int parent = current.parent;

            if (current.exit) {
                nodesByValue[nums[node]].Pop();
                continue;
            }

            int bestNode = -1;
            int bestDepth = -1;

            for (int value = 1; value <= 50; value++) {
                if (Gcd(nums[node], value) == 1 && nodesByValue[value].Count > 0) {
                    int candidate = nodesByValue[value].Peek();
                    if (depth[candidate] > bestDepth) {
                        bestDepth = depth[candidate];
                        bestNode = candidate;
                    }
                }
            }

            answer[node] = bestNode;
            nodesByValue[nums[node]].Push(node);

            events.Push((node, parent, true));

            for (int i = graph[node].Count - 1; i >= 0; i--) {
                int next = graph[node][i];
                if (next == parent) {
                    continue;
                }

                depth[next] = depth[node] + 1;
                events.Push((next, node, false));
            }
        }

        return answer;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }

        return a;
    }
}
