using System;
using System.Collections.Generic;

public class Solution
{
    private string[] _words;
    private string _result;
    private int[] _mapping;
    private bool[] _used;
    private bool[] _leading;
    private int _maxLength;

    public bool IsSolvable(string[] words, string result)
    {
        _words = words;
        _result = result;
        _mapping = new int[26];
        Array.Fill(_mapping, -1);
        _used = new bool[10];
        _leading = new bool[26];

        var present = new bool[26];
        int distinct = 0;

        foreach (string word in words)
        {
            if (word.Length > 1)
                _leading[word[0] - 'A'] = true;

            foreach (char ch in word)
            {
                int index = ch - 'A';
                if (!present[index])
                {
                    present[index] = true;
                    distinct++;
                }
            }
        }

        if (result.Length > 1)
            _leading[result[0] - 'A'] = true;

        foreach (char ch in result)
        {
            int index = ch - 'A';
            if (!present[index])
            {
                present[index] = true;
                distinct++;
            }
        }

        if (distinct > 10)
            return false;

        _maxLength = result.Length;
        foreach (string word in words)
            _maxLength = Math.Max(_maxLength, word.Length);

        return SearchColumn(0, 0);
    }

    private bool SearchColumn(int column, int carry)
    {
        if (column == _maxLength)
            return carry == 0;

        var addendLetters = new List<int>();

        foreach (string word in _words)
        {
            if (column < word.Length)
                addendLetters.Add(word[word.Length - 1 - column] - 'A');
        }

        int resultLetter = -1;
        if (column < _result.Length)
            resultLetter = _result[_result.Length - 1 - column] - 'A';

        return AssignAddends(addendLetters, resultLetter, 0, carry, column);
    }

    private bool AssignAddends(
        List<int> addendLetters,
        int resultLetter,
        int index,
        int sum,
        int column)
    {
        if (index < addendLetters.Count)
        {
            int letter = addendLetters[index];

            if (_mapping[letter] != -1)
                return AssignAddends(
                    addendLetters,
                    resultLetter,
                    index + 1,
                    sum + _mapping[letter],
                    column);

            for (int digit = 0; digit <= 9; digit++)
            {
                if (_used[digit])
                    continue;

                if (digit == 0 && _leading[letter])
                    continue;

                _mapping[letter] = digit;
                _used[digit] = true;

                if (AssignAddends(
                    addendLetters,
                    resultLetter,
                    index + 1,
                    sum + digit,
                    column))
                {
                    return true;
                }

                _mapping[letter] = -1;
                _used[digit] = false;
            }

            return false;
        }

        int requiredDigit = sum % 10;
        int nextCarry = sum / 10;

        if (resultLetter == -1)
        {
            if (requiredDigit != 0)
                return false;

            return SearchColumn(column + 1, nextCarry);
        }

        if (_mapping[resultLetter] != -1)
        {
            if (_mapping[resultLetter] != requiredDigit)
                return false;

            return SearchColumn(column + 1, nextCarry);
        }

        if (_used[requiredDigit])
            return false;

        if (requiredDigit == 0 && _leading[resultLetter])
            return false;

        _mapping[resultLetter] = requiredDigit;
        _used[requiredDigit] = true;

        if (SearchColumn(column + 1, nextCarry))
            return true;

        _mapping[resultLetter] = -1;
        _used[requiredDigit] = false;

        return false;
    }
}
