                i++;
                j++;
            }
            else if (j < p.Length && p[j] == '*') {
                star = j;
                match = i;
                j++;
            }
            else if (star != -1) {
                j = star + 1;
                match++;
                i = match;
            }
            else {
                return false;
            }
        }

        while (j < p.Length && p[j] == '*') {
            j++;
        }

        return j == p.Length;
    }
